test('chooseSample picks the rows that break expressions, not just the first ones', () => {
  const columns = [{ name: 'A' }]
  const items = Array.from({ length: 50 }, (_, i) => ({ A: String(i) }))
  items[20] = { A: '' }
  items[30] = { A: 'not a number' }
  const profiles = columns.map((c) => profileColumn(c, items))
  const reasons = new Map(chooseSample(columns, items, profiles).map((s) => [s.rowIndex, s.reason]))
  // Row 20 is the empty cell, row 30 the longest value and the one that does
  // not parse. Some rows are picked at random first and keep that reason, so
  // only their presence is certain.
  expect(reasons.has(20)).toBe(true)
  expect(reasons.has(30)).toBe(true)
  expect(reasons.get(0)).toBe('head')
  expect(reasons.get(49)).toBe('tail')
})

import { describe, expect, test } from 'bun:test'
import { evaluateScript, type ScriptTarget } from './evaluate'
import type { TableDocument } from './tableDoc'

const doc: TableDocument = {
  columns: [
    { name: 'Amount', type: '' },
    { name: 'Double', type: 'Computed', expression: "return dbl(Number(item['Amount']))" },
    { name: 'Next', type: '' },
  ],
  items: [{ Amount: '1' }, { Amount: '2' }, { Amount: '3' }],
  customFunctions: 'function dbl(x){return x*2}',
  stats: { widgets: [{ id: 'w', title: 't', type: 'stat', expression: 'return 1' }] },
}

const outputs = (target: ScriptTarget, code: string, column: string | null = 'Amount') =>
  evaluateScript(doc, target, code, column).sample.map((s) => s.output)

describe('sandbox', () => {
  // Each root is a way to reach a Function constructor. If any of them belongs
  // to the host realm, the function it builds can see process.env.
  const roots = [
    'items.constructor.constructor',
    'item.constructor.constructor',
    'this.constructor.constructor',
    'globalThis.constructor.constructor',
    'columnName.constructor.constructor',
    'console.log.constructor',
    '__input.constructor.constructor',
    'JSON.parse.constructor',
    '(function(){ return this })().constructor.constructor',
  ]
  const probe = (root: string) =>
    `throw new Error('got:' + ${root}('return typeof process')())`

  for (const root of roots) {
    test(`${root} cannot reach process`, () => {
      const result = evaluateScript(doc, 'computed', probe(root), 'Amount')
      expect(result.errors[0]?.message).toBe('got:undefined')
    })
  }

  test('the startup script cannot reach process either', () => {
    const result = evaluateScript(doc, 'startup', probe('rows.constructor.constructor'), null)
    expect(result.errors[0]?.message).toBe('got:undefined')
  })

  test('a script that never finishes is reported, not hung on', () => {
    const result = evaluateScript(doc, 'computed', 'while(true){}', 'Amount', { timeoutMs: 200 })
    expect(result.timedOut).toBe(true)
    expect(result.rowsEvaluated).toBe(0)
  })

  test('nor is one that leaves the endless part for after it returns', () => {
    for (const code of ['Promise.resolve().then(() => { for (;;) {} }); return 1', '(async () => { await null; for (;;) {} })(); return 1']) {
      const result = evaluateScript(doc, 'computed', code, 'Amount', { timeoutMs: 200 })
      expect(result.timedOut).toBe(true)
    }
  })
})

describe('harness matches the app', () => {
  test('reading a computed column yields its computed value', () => {
    expect(outputs('computed', "return item['Double'] + 1", 'Next')).toEqual(['3', '5', '7'])
  })

  test('a candidate is its column from then on, so a cycle through it reads null as in the app', () => {
    // Double reads Amount. Making Amount computed from Double closes a loop.
    expect(outputs('computed', "return item['Double'] + 1", 'Amount')).toEqual(['1', '1', '1'])
  })

  test('Object.prototype methods on a row are not mistaken for columns', () => {
    expect(outputs('computed', "return String(item.hasOwnProperty('Amount'))")).toEqual([
      'true',
      'true',
      'true',
    ])
  })

  test('totals see enriched rows and the helpers', () => {
    expect(outputs('total', "return items.reduce((a, r) => a + r['Double'], 0)")).toEqual(['12'])
  })

  test('stats widgets do not get customFunctions', () => {
    expect(outputs('statsWidget', 'return typeof dbl', null)).toEqual(['undefined'])
  })

  // items is a Proxy, and for..of, spread and Array.from read its
  // Symbol.iterator before any index. The app runs these, so refusing them
  // here would refuse a script that works.
  test('for..of walks the rows, enriched, in every target that gets items', () => {
    const forOf = "let out = ''; for (const r of items) out += r['Double']; return out"
    expect(outputs('computed', forOf, 'Next')).toEqual(['246', '246', '246'])
    expect(outputs('total', forOf)).toEqual(['246'])
    expect(outputs('statsWidget', forOf, null)).toEqual(['246'])
  })

  test('spread and Array.from too', () => {
    expect(outputs('total', 'return [...items].length')).toEqual(['3'])
    expect(outputs('total', "return Array.from(items, (r) => r['Double']).join('-')")).toEqual(['2-4-6'])
  })

  test('rows reached by iteration are counted as dependencies', () => {
    const cost = (code: string) => evaluateScript(doc, 'total', code, 'Amount').cost.dependencyEntries
    // Three rows read once each, the same as reaching them by index.
    expect(cost("let n = 0; for (const r of items) n += Number(r['Amount']); return n")).toBe(
      cost("let n = 0; for (let i = 0; i < items.length; i++) n += Number(items[i]['Amount']); return n"),
    )
  })

  test('the startup script works on a copy of the rows', () => {
    expect(outputs('startup', "rows.push({ Amount: '9' })", null)).toEqual(['rows after script: 4'])
    expect(doc.items).toHaveLength(3)
  })

  test('a pull script may await, and a dry run only compiles it', () => {
    const result = evaluateScript(doc, 'pull', "const a = await integration('X').get('/'); rows.push(a)", null)
    expect(result.compiled).toBe(true)
    expect(result.errors).toEqual([])
    expect(result.sample[0]?.output).toContain('only Pull in the app runs it')
    expect(evaluateScript(doc, 'pull', 'rows.push(', null).compiled).toBe(false)
  })
})

describe('failures', () => {
  test('a syntax error is a result, not an exception', () => {
    const result = evaluateScript(doc, 'computed', 'return (', 'Amount')
    expect(result.compiled).toBe(false)
    expect(result.errors[0]?.message).toStartWith('does not compile')
  })

  test('helpers that do not compile are caught', () => {
    expect(evaluateScript(doc, 'customFns', 'function (', null).compiled).toBe(false)
    expect(evaluateScript(doc, 'customFns', 'function ok(){}', null).compiled).toBe(true)
  })

  test('throwing on every row is countable as such', () => {
    const result = evaluateScript(doc, 'computed', 'return nope()', 'Amount')
    expect(result.threw).toBe(result.rowsEvaluated)
    expect(result.errors[0]?.rowIndex).toBe(0)
  })
})

describe('cost', () => {
  const big: TableDocument = {
    columns: [{ name: 'Amount' }, { name: 'Run' }],
    items: Array.from({ length: 200 }, (_, i) => ({ Amount: String(i) })),
  }

  test('a running total that rereads every earlier row is flagged', () => {
    const code = "return items.slice(0, rowIndex + 1).reduce((a, r) => a + Number(r['Amount']), 0)"
    expect(evaluateScript(big, 'computed', code, 'Run').cost.growsWithRowIndex).toBe(true)
  })

  test('a per-row expression is not', () => {
    const result = evaluateScript(big, 'computed', "return Number(item['Amount']) * 2", 'Run')
    expect(result.cost.growsWithRowIndex).toBe(false)
    expect(result.cost.dependencyEntries).toBe(200)
  })
})

import { describe, expect, test } from 'bun:test'
import { pageText, snippetAround } from './pageText'

describe('what a page says', () => {
  test('a Flat Page reads as its text, not its HTML', () => {
    const link = '<a href="https://x.test" target="_blank" contenteditable="false">a link</a>'
    expect(pageText('FlatPage', `<div>Milk and <b>bread</b></div><div>then ${link}</div>`)).toBe('Milk and **bread**\nthen [a link](https://x.test)')
  })

  test('formatting the line form cannot express still reads as plain text', () => {
    expect(pageText('FlatPage', '<div><span style="color: red">Urgent</span> today</div>')).toBe('Urgent today')
  })

  test('a Flat Page v2 reads as its text, not its ProseMirror JSON', () => {
    const doc = JSON.stringify({
      type: 'doc',
      content: [
        { type: 'heading', attrs: { level: 2 }, content: [{ type: 'text', text: 'Shopping' }] },
        { type: 'paragraph', content: [{ type: 'text', text: 'Bread and milk' }] },
      ],
    })
    expect(pageText('FlatPageV2', doc)).toBe('## Shopping\nBread and milk')
  })

  test('a Table reads as its rows, keyed by column', () => {
    const doc = JSON.stringify({
      columns: [{ name: 'Item' }, { name: 'Price', label: 'Cost' }],
      items: [{ Item: '<b>Bread</b>', Price: '55' }, { Item: 'Milk', Price: '' }],
      totals: {},
    })
    expect(pageText('Table', doc)).toBe('Item | Cost\nItem: Bread | Price: 55\nItem: Milk')
  })

  test('a Mini App reads as its code and what it has stored', () => {
    const files = { html: '<div id="app"></div>', css: '', js: 'const total = 1', modules: [{ name: 'helpers.js', code: 'export const one = 1' }] }
    expect(pageText('MiniApp', JSON.stringify({ files, kv: {} }))).toBe('<div id="app"></div>\nconst total = 1\nhelpers.js\nexport const one = 1')
    // The stored data is indexed with the code, so a search that matched an
    // item has to be able to find that item in what is shown.
    const withData = JSON.stringify({ files, kv: { items: [{ text: 'ring the plumber', done: false }] } })
    expect(pageText('MiniApp', withData)).toEndWith('ring the plumber')
    // Stored data is not a document shape: a key named type holds a value the
    // app means to show, unlike the node names of a Rich Text page.
    const tagged = JSON.stringify({ files, kv: { entries: [{ type: 'groceries', note: 'milk' }] } })
    expect(pageText('MiniApp', tagged)).toEndWith('groceries\nmilk')
  })

  test('a page type with no codec here still gives up its text', () => {
    // Rich Text is Editor.js blocks; Kanban and Spreadsheet v2 are their own shapes.
    const doc = JSON.stringify({ time: 1, blocks: [{ type: 'paragraph', data: { text: 'A <b>note</b> here' } }] })
    // The node names are shape, not text: "paragraph" would crowd out the page.
    expect(pageText('RichText', doc)).toBe('A note here')
  })

  test('dropping the shape keys keeps what the page says', () => {
    const board = JSON.stringify({ boards: [{ id: '1789', title: 'Doing', cards: [{ id: '1790', title: 'Fix the boiler', description: 'ring the plumber' }] }] })
    expect(pageText('Kanban', board)).toBe('Doing\nFix the boiler\nring the plumber')
  })

  test('XML content comes back without its tags', () => {
    expect(pageText('DrawIO', '<mxfile><diagram>Flow chart</diagram></mxfile>')).toBe('Flow chart')
  })

  test('nothing to read is nothing to show', () => {
    expect(pageText('FlatPage', null)).toBeNull()
    expect(pageText('MiniApp', 'not json')).toBeNull()
  })
})

describe('the window around a match', () => {
  const long = (word: string) => `${'filler '.repeat(60)}${word} ${'more '.repeat(60)}`

  test('short text comes back whole', () => {
    expect(snippetAround('Bread and milk', 'milk')).toBe('Bread and milk')
  })

  test('a long page is windowed around the match', () => {
    const snippet = snippetAround(long('needle'), 'needle')
    expect(snippet).toContain('needle')
    expect(snippet.startsWith('...')).toBe(true)
    expect(snippet.endsWith('...')).toBe(true)
    expect(snippet.length).toBeLessThan(260)
  })

  test('a multi-word query falls back to its longest word', () => {
    expect(snippetAround(long('reconciliation'), 'the reconciliation report')).toContain('reconciliation')
  })

  test('text that matched on something the decoder dropped still shows the start', () => {
    expect(snippetAround(long('elsewhere'), 'nowhere')).toStartWith('filler')
  })

  test('no markers are added, so a snippet cannot be mistaken for markup', () => {
    expect(snippetAround('Bread and milk', 'milk')).not.toContain('*')
  })

  test('whitespace is collapsed', () => {
    expect(snippetAround('Bread\n\nand   milk', 'milk')).toBe('Bread and milk')
  })
})

import { describe, expect, test } from 'bun:test'
import { editRows, readRows } from './tableRows'
import type { TableDocument } from './tableDoc'

const LINK = '<a data-page-id="42" class="page-link" href="/page/42" target="_blank" contenteditable="false">Recipes</a>'

const table = (): TableDocument => ({
  columns: [
    { name: 'Item', type: '' },
    { name: 'Amount', type: '' },
    { name: 'Double', type: 'Computed', expression: "return dbl(Number(String(item['Amount']).replace(/<[^>]*>/g, '')))" },
  ],
  items: [
    { Item: 'milk', Amount: '2', Double: '' },
    { Item: `<b>eggs</b> from ${LINK}`, Amount: '<b>3</b>', Double: '' },
    { Item: '<span style="color: red;">bread</span>', Amount: 'n/a', Double: '' },
    { Item: 'oat milk', Amount: '5', Double: '' },
  ],
  totals: { Amount: "return items.reduce((a, r) => a + (Number(String(r['Amount']).replace(/<[^>]*>/g, '')) || 0), 0)" },
  widths: { Item: '200px' },
  customFunctions: 'function dbl(x){return x*2}',
})

describe('readRows', () => {
  test('cells as text, computed columns as what they show', () => {
    const result = readRows(table(), {})
    expect(result.rowCount).toBe(4)
    expect(result.columns).toEqual([{ name: 'Item' }, { name: 'Amount' }, { name: 'Double', computed: true }])
    expect(result.rows).toEqual([
      { row: 0, values: { Item: 'milk', Amount: '2', Double: '4' } },
      { row: 1, values: { Item: '**eggs** from [[Recipes|42]]', Amount: '**3**', Double: '6' } },
      // Styling the cell form cannot express reads as its text.
      { row: 2, values: { Item: 'bread', Amount: 'n/a', Double: 'NaN' } },
      { row: 3, values: { Item: 'oat milk', Amount: '5', Double: '10' } },
    ])
  })

  test('windows, from either end', () => {
    expect(readRows(table(), { start: 1, limit: 2 }).rows.map((r) => r.row)).toEqual([1, 2])
    expect(readRows(table(), { start: -1 }).rows.map((r) => r.row)).toEqual([3])
    expect(readRows(table(), { start: 99 }).rows).toEqual([])
  })

  test('search keeps real row numbers and says how many matched', () => {
    const result = readRows(table(), { search: 'MILK' })
    expect(result.matched).toBe(2)
    expect(result.rows.map((r) => r.row)).toEqual([0, 3])
    // Computed values are still right for a row that is not first in the window.
    expect(result.rows[1]!.values.Double).toBe('10')
  })

  test('choosing columns, and a computed column left out is not run', () => {
    const doc = table()
    doc.columns[2]!.expression = 'while(true){}'
    expect(readRows(doc, { columns: ['Item'], limit: 1 }).rows).toEqual([{ row: 0, values: { Item: 'milk' } }])
    expect(() => readRows(doc, { columns: ['Nope'] })).toThrow(/This table has: Item, Amount, Double/)
  })

  test('a computed column that throws or hangs is reported in the cell, not as a failed read', () => {
    const throws = table()
    throws.columns[2]!.expression = "if (rowIndex === 1) throw new Error('bad row'); return 1"
    expect(readRows(throws, {}).rows.map((r) => r.values.Double)).toEqual(['1', '#ERROR bad row', '1', '1'])
    const hangs = table()
    hangs.columns[2]!.expression = 'while(true){}'
    expect(readRows(hangs, { limit: 1 }).rows[0]!.values.Double).toMatch(/^#ERROR did not finish/)
  })

  test('totals on request', () => {
    expect(readRows(table(), {}).totals).toBeUndefined()
    expect(readRows(table(), { totals: true }).totals).toEqual({ Amount: '10' })
  })

  test('a never-saved table has no rows and no columns', () => {
    expect(readRows({ columns: [], items: [] }, {})).toMatchObject({ rowCount: 0, columns: [], rows: [] })
  })
})

describe('editRows', () => {
  test('update touches only the named cells', () => {
    const doc = table()
    editRows(doc, { update: [{ row: 1, values: { Amount: 4 } }] })
    expect(doc.items[1]).toEqual({ Item: `<b>eggs</b> from ${LINK}`, Amount: '4', Double: '' })
  })

  test('new rows carry every stored column, and cell text becomes the HTML the app writes', () => {
    const doc = table()
    const summary = editRows(doc, { add: [{ Item: '**rice** & [[Recipes|42]]', Amount: 1.5 }, { Item: '<script>x</script>' }] })
    expect(summary).toEqual({ updated: 0, removed: 0, added: 2, firstAdded: 4 })
    expect(doc.items.slice(4)).toEqual([
      { Item: `<b>rice</b> &amp; ${LINK}`, Amount: '1.5' },
      { Item: '&lt;script&gt;x&lt;/script&gt;', Amount: '' },
    ])
  })

  test('row numbers mean the table as it was read, whatever else the batch does', () => {
    const doc = table()
    const summary = editRows(doc, {
      update: [{ row: 3, values: { Amount: '6' } }],
      remove: [0, 2],
      add: [{ Item: 'new' }],
      addBefore: 3,
    })
    expect(doc.items.map((r) => [r.Item, r.Amount])).toEqual([[`<b>eggs</b> from ${LINK}`, '<b>3</b>'], ['new', ''], ['oat milk', '6']])
    expect(summary.firstAdded).toBe(1)
  })

  test('a bad batch changes nothing', () => {
    const doc = table()
    const before = JSON.stringify(doc)
    expect(() => editRows(doc, { update: [{ row: 0, values: { Amount: '9' } }, { row: 4, values: { Amount: '9' } }] })).toThrow(/Row 4 does not exist. Rows are numbered 0 to 3/)
    expect(() => editRows(doc, { add: [{ Item: 'ok' }, { Price: '1' }] })).toThrow(/No column named Price/)
    expect(() => editRows(doc, { update: [{ row: 0, values: { Double: '1' } }] })).toThrow(/computed column/)
    expect(() => editRows(doc, { add: [{ Item: 'two\nlines' }] })).toThrow(/one line/)
    expect(() => editRows(doc, { add: [{ Item: '[x](javascript:alert(1))' }] })).toThrow(/http/)
    expect(() => editRows(doc, {})).toThrow(/Nothing to change/)
    expect(() => editRows(doc, { remove: [0], addBefore: 1 })).toThrow(/addBefore/)
    expect(JSON.stringify(doc)).toBe(before)
  })

  test("adding to a new table replaces the app's blank placeholder row", () => {
    const doc: TableDocument = { columns: [{ name: 'A' }, { name: 'B' }], items: [{ A: '', B: '<br>' }] }
    expect(editRows(doc, { add: [{ A: '1' }, { A: '2' }] }).firstAdded).toBe(0)
    expect(doc.items).toEqual([{ A: '1', B: '' }, { A: '2', B: '' }])
    // A single row with something in it is data, and stays.
    const real: TableDocument = { columns: [{ name: 'A' }], items: [{ A: 'x' }] }
    editRows(real, { add: [{ A: 'y' }] })
    expect(real.items).toEqual([{ A: 'x' }, { A: 'y' }])
  })

  test('removing every row leaves one blank row, as the app does', () => {
    const doc = table()
    editRows(doc, { remove: [0, 1, 2, 3, 3] })
    expect(doc.items).toEqual([{ Item: '', Amount: '' }])
  })

  test('the rest of the document is untouched', () => {
    const doc = table()
    editRows(doc, { add: [{ Item: 'x' }] })
    const fresh = table()
    expect({ ...doc, items: [] }).toEqual({ ...fresh, items: [] })
  })
})

