test('a line is editable only when sending it back unchanged would change nothing', () => {
  const echo = (html: string) => {
    const [unit] = flatCodec.read(html)
    return unit!.readOnly ? 'read-only' : flatCodec.parse(unit!.lines)[0]!.data.html
  }
  // The app's own shapes come back as themselves.
  for (const html of [
    '<div>plain &amp; simple</div>',
    '<div><b>bold</b> <i>it</i> <strike>gone</strike> <code>x</code></div>',
    `<div>${LINK}</div>`,
    '<div><a href="https://a.example" target="_blank" contenteditable="false">site</a></div>',
    '<div><img style="max-width: 100%" loading="lazy" src="https://a.example/i.png"></div>',
    '<div><br></div>',
  ]) {
    expect(echo(html)).toBe(html)
  }
  // The browser re-serialises the image style with a semicolon. Still the app's image.
  expect(echo('<div><img style="max-width: 100%;" loading="lazy" src="https://a.example/i.png"></div>')).not.toBe('read-only')
  // Anything the line form would lose makes the line read-only instead.
  for (const html of [
    '<div><a href="https://a.example/(x)" target="_blank" contenteditable="false">paren in address</a></div>',
    '<div><img id="i1" width="40" src="https://a.example/i.png"></div>',
    '<div><code><b>bold inside code</b></code></div>',
    '<div><a href="javascript:alert(1)">bad address</a></div>',
    '<div><strong>pasted strong</strong></div>',
    '<div>two\nsource lines</div>',
  ]) {
    expect(echo(html)).toBe('read-only')
  }
})

test('any line that parses reads back as it was written', () => {
  const nbsp = String.fromCharCode(160)
  const fragments = ['plain', '', '  indented', 'a  b   c ', '**b** *i* ~~s~~ `c`', '***both***', '[[P|3]]', '[l](https://a.b)', '![](https://a.b/i.png)', 'a<br>b', 'end<br>', '\ttab', `n${nbsp}b`, '<b>tag</b> & "quotes"', '\\*literal\\*', '2 * 3 * 4', '# not a heading', '- not a list']
  let seed = 11
  const next = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648
  for (let round = 0; round < 300; round++) {
    const lines = Array.from({ length: 1 + Math.floor(next() * 3) }, () => fragments[Math.floor(next() * fragments.length)]!)
    // Joined into one line as well, so fragments meet each other mid-line.
    for (const text of [lines, [lines.join(' ')]]) {
      const written = flatCodec.parse(text)
      expect(linesOf(flatCodec.read(flatCodec.write(written)))).toEqual(linesOf(written))
    }
  }
})

import { Schema, type NodeSpec } from 'prosemirror-model'

/**
 * Test only. The editors' schemas, rebuilt from the Tiptap extension lists at
 * FlatPageV2.svelte:171-208 and TaskList.svelte:22-45, so tests can check that
 * a document this server writes is one the app can load. A Flat Page v2 page
 * whose content fails to load stays on "Loading..." forever.
 *
 * When an editor gains a node or an attribute, add it here too.
 */

const cell: NodeSpec = {
  content: 'block+',
  attrs: { colspan: { default: 1 }, rowspan: { default: 1 }, colwidth: { default: null }, align: { default: null }, nowrap: { default: false } },
}

const marks = { bold: {}, code: { excludes: '_' }, italic: {}, strike: {} }

const shared: Record<string, NodeSpec> = {
  paragraph: { content: 'inline*', group: 'block' },
  text: { group: 'inline' },
  hardBreak: { inline: true, group: 'inline' },
  taskList: { content: 'taskItem+', group: 'block list' },
  taskItem: { content: 'paragraph block*', attrs: { checked: { default: false } } },
}

export const flatPageV2Schema = new Schema({
  nodes: {
    doc: { content: 'block+' },
    ...shared,
    heading: { content: 'inline*', group: 'block', attrs: { level: { default: 1 } } },
    codeBlock: { content: 'text*', marks: '', group: 'block', code: true, attrs: { language: { default: null } } },
    bulletList: { content: 'listItem+', group: 'block list' },
    orderedList: { content: 'listItem+', group: 'block list', attrs: { start: { default: 1 }, type: { default: null } } },
    listItem: { content: 'paragraph block*' },
    pageLink: { inline: true, group: 'inline', atom: true, attrs: { pageId: { default: null }, pageName: { default: '' } } },
    externalLink: { inline: true, group: 'inline', atom: true, attrs: { href: { default: null }, label: { default: '' } } },
    image: { inline: true, group: 'inline', atom: true, attrs: { src: { default: null }, alt: { default: null }, title: { default: null } } },
    table: { content: 'tableRow+', group: 'block' },
    tableRow: { content: '(tableCell | tableHeader)*' },
    tableHeader: cell,
    tableCell: cell,
  },
  marks,
})

export const taskListSchema = new Schema({ nodes: { doc: { content: 'taskList' }, ...shared }, marks })

/** Throws when the content is not a document the editor would accept. */
export function assertLoads(schema: Schema, content: string): void {
  schema.nodeFromJSON(JSON.parse(content)).check()
}

import { describe, expect, test } from 'bun:test'
import { CodecError, type Inline, parseInline, renderInline } from './inline'

const parse = (s: string) => parseInline(s, { links: true })
const text = (t: string, ...marks: Inline['marks']): Inline => ({ kind: 'text', text: t, marks })

describe('parseInline', () => {
  test('marks', () => {
    expect(parse('a **b** *c* ~~d~~ `e`')).toEqual([
      text('a '), text('b', 'bold'), text(' '), text('c', 'italic'), text(' '), text('d', 'strike'), text(' '), text('e', 'code'),
    ])
  })

  test('nested marks come out in the order the editor stores them', () => {
    expect(parse('***x***')).toEqual([text('x', 'bold', 'italic')])
    expect(parse('*a **b***')).toEqual([text('a ', 'italic'), text('b', 'bold', 'italic')])
  })

  test('arithmetic and lone delimiters are text', () => {
    expect(parse('2 * 3 * 4')).toEqual([text('2 * 3 * 4')])
    expect(parse('a * b')).toEqual([text('a * b')])
    expect(parse('5* stars')).toEqual([text('5* stars')])
    expect(parse('**bold** and a stray ** here')).toEqual([text('bold', 'bold'), text(' and a stray ** here')])
    expect(parse('a ` b')).toEqual([text('a ` b')])
  })

  test('code spans are raw', () => {
    expect(parse('`**x** [a](b)`')).toEqual([text('**x** [a](b)', 'code')])
  })

  test('links, page links, images and breaks', () => {
    expect(parse('see [[Recipes|42]] or [site](https://a.b/c)<br>![cat](https://a.b/c.png "Cat")')).toEqual([
      text('see '),
      { kind: 'pageLink', pageId: 42, pageName: 'Recipes', marks: [] },
      text(' or '),
      { kind: 'link', href: 'https://a.b/c', label: 'site', marks: [] },
      { kind: 'break', marks: [] },
      { kind: 'image', src: 'https://a.b/c.png', alt: 'cat', title: 'Cat', marks: [] },
    ])
  })

  test('a page link without an id is an error that says how to write one', () => {
    expect(() => parse('[[Recipes]]')).toThrow(CodecError)
    expect(() => parse('[[Recipes]]')).toThrow(/\[\[Page name\|id\]\]/)
  })

  test('only web and mail addresses are accepted, since Flat Page renders links as HTML', () => {
    expect(() => parse('[x](javascript:alert(1))')).toThrow(/http/)
    expect(() => parse('![x](data:image/png;base64,AAAA)')).toThrow(/http/)
    expect(parse('[mail](mailto:a@b.c)')[0]).toMatchObject({ kind: 'link', href: 'mailto:a@b.c' })
  })

  test('with links off, as on a Task List, link syntax is just text', () => {
    expect(parseInline('[a](https://b) [[P|1]]', { links: false })).toEqual([text('[a](https://b) [[P|1]]')])
  })

  test('brackets that are not a link stay text', () => {
    expect(parse('[todo] and [x](not a url')).toEqual([text('[todo] and [x](not a url')])
  })
})

describe('round trip', () => {
  const samples: Inline[][] = [
    [text('plain')],
    [text('a * b ** c ` d [e] ~~ f \\ g <br> h')],
    [text('[[not a link|1]] and [label](https://x)')],
    [text('trailing space ', 'bold'), text('next')],
    [text('both', 'bold', 'italic', 'strike')],
    [text('a', 'italic'), text('b', 'bold'), text('c', 'bold', 'italic')],
    [text('x', 'code'), text(' then '), text('y', 'bold')],
    [{ kind: 'pageLink', pageId: 7, pageName: 'Pipes | and ] brackets', marks: [] }],
    [{ kind: 'link', href: 'https://a.b/?q=1&r=2', label: 'a ] b', marks: ['bold'] }],
    [{ kind: 'image', src: 'https://a.b/c.png', alt: null, title: null, marks: [] }],
    [text('line one'), { kind: 'break', marks: [] }, text('line two')],
  ]
  for (const tokens of samples) {
    test(renderInline(tokens), () => {
      expect(parse(renderInline(tokens))).toEqual(tokens)
    })
  }
})

import assert from 'node:assert/strict'
import { existsSync, readFileSync } from 'node:fs'
import test from 'node:test'
import { DatabaseSync } from 'node:sqlite'

const orderPath = new URL('../src/page_history_order.cr', import.meta.url)

test('shared newest-first order resolves equal timestamps by descending ID', () => {
    assert.ok(existsSync(orderPath), 'shared page-history order is missing')

    const source = readFileSync(orderPath, 'utf8')
    const match = source.match(
        /PAGE_HISTORY_ORDER_NEWEST_FIRST\s*=\s*"([^"]+)"/,
    )
    assert.ok(match, 'shared page-history order constant is missing')

    const db = new DatabaseSync(':memory:')
    db.exec(`
        CREATE TABLE page_history (
            id INTEGER PRIMARY KEY,
            content TEXT,
            created_at TIMESTAMP
        );
        INSERT INTO page_history(content, created_at)
        VALUES ('first', '2026-07-16 12:00:00');
        INSERT INTO page_history(content, created_at)
        VALUES ('second', '2026-07-16 12:00:00');
    `)

    const rows = db
        .prepare(`SELECT content FROM page_history ORDER BY ${match[1]}`)
        .all()
    assert.deepEqual(
        rows.map((row) => row.content),
        ['second', 'first'],
    )
})

test('all newest-first page-history queries use the shared order', () => {
    const main = readFileSync(new URL('../src/main.cr', import.meta.url), 'utf8')
    const routes = readFileSync(
        new URL('../src/routes.cr', import.meta.url),
        'utf8',
    )
    const miniAppRoutes = readFileSync(
        new URL('../src/miniapp_routes.cr', import.meta.url),
        'utf8',
    )
    const usage = /ORDER BY #\{PAGE_HISTORY_ORDER_NEWEST_FIRST\}/g

    assert.match(main, /require "\.\/page_history_order"/)
    assert.equal(routes.match(usage)?.length, 2)
    assert.equal(miniAppRoutes.match(usage)?.length, 1)
})
